<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder\MessageTargetAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageTargetAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class MessageTargetAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTarget returns null on a freshly created holder.
     */
    public function testTargetNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithMessageTargetAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTargetAssigned());
        $this->assertNull($holder->getTarget());
    }
}
class ImplWithMessageTargetAttributeHolderUnitTest
{
    use MessageTargetAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTargetRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTarget();
    }
}
